namespace {
void checkImpl(bool v,int line){if(!v)throw std::runtime_error("Network regression failed at line "+std::to_string(line));}
#define check(v) checkImpl((v),__LINE__)
void near(double a,double b){if(!(std::isfinite(a)&&std::abs(a-b)<=1e-9*std::max({1e-300,std::abs(a),std::abs(b)})))throw std::runtime_error("Network numeric mismatch "+std::to_string(a)+" != "+std::to_string(b));}
void flowCertificate(const Graph& g,std::size_t source,std::size_t sink,const MaximumFlow& r){
 check(r.edgeFlow.size()==g.edges.size()&&r.sourceSide.size()==g.nodeCount&&r.sourceSide[source]&&!r.sourceSide[sink]);
 std::vector<double> net(g.nodeCount),replay(g.edges.size());double cut=0,total=0;
 for(std::size_t i=0;i<g.edges.size();++i){const auto& e=g.edges[i];check(r.edgeFlow[i]>=0&&r.edgeFlow[i]<=e.value);net[e.from]-=r.edgeFlow[i];net[e.to]+=r.edgeFlow[i];if(r.sourceSide[e.from]&&!r.sourceSide[e.to])cut+=e.value;}
 for(std::size_t i=0;i<g.nodeCount;++i)near(net[i],i==source?-r.value:i==sink?r.value:0);
 near(cut,r.value);near(r.cutCapacity,r.value);
 if(!r.trace.empty()&&!r.traceTruncated){for(const auto& step:r.trace){check(step.nodes.front()==source&&step.nodes.back()==sink&&step.edgeIndices.size()+1==step.nodes.size());for(std::size_t j=0;j<step.edgeIndices.size();++j){const auto i=step.edgeIndices[j];const auto& e=g.edges[i];check(step.nodes[j]==(step.backward[j]?e.to:e.from));check(step.nodes[j+1]==(step.backward[j]?e.from:e.to));replay[i]+=step.backward[j]?-step.amount:step.amount;}total+=step.amount;}near(total,r.value);for(std::size_t i=0;i<replay.size();++i)near(replay[i],r.edgeFlow[i]);}
}
double minimumCut(const Graph& g,std::size_t source,std::size_t sink){double best=INFINITY;for(unsigned mask=0;mask<(1u<<g.nodeCount);++mask){if(!(mask&(1u<<source))||(mask&(1u<<sink)))continue;double value=0;for(const auto& e:g.edges)if((mask&(1u<<e.from))&&!(mask&(1u<<e.to)))value+=e.value;best=std::min(best,value);}return best;}
unsigned bitCount(unsigned mask){unsigned n=0;while(mask){n+=mask&1u;mask>>=1u;}return n;}
double bruteTree(const Graph& g){double best=INFINITY;for(unsigned mask=0;mask<(1u<<g.edges.size());++mask){if(static_cast<std::size_t>(bitCount(mask))!=g.nodeCount-1)continue;std::vector<std::size_t> parent(g.nodeCount);std::iota(parent.begin(),parent.end(),0);auto root=[&](std::size_t a){while(parent[a]!=a)a=parent[a];return a;};bool cycle=false;double value=0;for(std::size_t i=0;i<g.edges.size();++i)if(mask&(1u<<i)){const auto& e=g.edges[i];auto a=root(e.from),b=root(e.to);if(a==b){cycle=true;break;}parent[a]=b;value+=e.value;}if(!cycle)best=std::min(best,value);}return best;}
void routeCertificate(const Graph& g,const ShortestRoutes& r){
 std::vector<double> labels(g.nodeCount,INFINITY);labels[r.source]=0;std::size_t lastPass=0;for(const auto& step:r.trace){check(step.pass>=lastPass&&step.pass<g.nodeCount);lastPass=step.pass;const auto& edge=g.edges.at(step.edgeIndex);check((edge.from==step.from&&edge.to==step.to)||(!g.directed&&edge.to==step.from&&edge.from==step.to));near(step.distance,labels[step.from]+edge.value);check(step.distance<labels[step.to]);labels[step.to]=step.distance;}
 const auto n=g.nodeCount;std::vector<std::vector<double>> d(n,std::vector<double>(n,INFINITY));for(std::size_t i=0;i<n;++i)d[i][i]=0;for(const auto& e:g.edges){d[e.from][e.to]=std::min(d[e.from][e.to],e.value);if(!g.directed)d[e.to][e.from]=std::min(d[e.to][e.from],e.value);}for(std::size_t k=0;k<n;++k)for(std::size_t i=0;i<n;++i)for(std::size_t j=0;j<n;++j)if(std::isfinite(d[i][k])&&std::isfinite(d[k][j]))d[i][j]=std::min(d[i][j],d[i][k]+d[k][j]);
 for(std::size_t target=0;target<n;++target){const auto& route=r.routes[target];bool cycle=false;for(std::size_t k=0;k<n;++k)cycle|=d[k][k]<0&&std::isfinite(d[r.source][k])&&std::isfinite(d[k][target]);if(cycle){check(route.status==RouteStatus::NegativeCycle&&!route.distance);continue;}if(!std::isfinite(d[r.source][target])){check(route.status==RouteStatus::Unreachable&&!route.distance);continue;}check(route.status==RouteStatus::Finite&&route.distance);near(*route.distance,d[r.source][target]);check(route.nodes.front()==r.source&&route.nodes.back()==target&&route.nodes.size()==route.edgeIndices.size()+1);double weight=0;for(std::size_t j=0;j<route.edgeIndices.size();++j){const auto& e=g.edges[route.edgeIndices[j]];check((e.from==route.nodes[j]&&e.to==route.nodes[j+1])||(!g.directed&&e.to==route.nodes[j]&&e.from==route.nodes[j+1]));weight+=e.value;}near(weight,*route.distance);}
 if(!r.negativeCycleNodes.empty()){check(r.negativeCycleNodes.front()==r.negativeCycleNodes.back());double weight=0;for(std::size_t j=0;j<r.negativeCycleEdges.size();++j){const auto& e=g.edges[r.negativeCycleEdges[j]];check((e.from==r.negativeCycleNodes[j]&&e.to==r.negativeCycleNodes[j+1])||(!g.directed&&e.to==r.negativeCycleNodes[j]&&e.from==r.negativeCycleNodes[j+1]));weight+=e.value;}check(weight<0);}
}
void dijkstraCertificate(const Graph& g,std::size_t source){auto r=dijkstra(g,source);routeCertificate(g,r);std::vector<bool> permanent(g.nodeCount);double last=0;for(const auto& step:r.dijkstraTrace){check(!permanent[step.permanentNode]);permanent[step.permanentNode]=true;check(step.permanent==permanent&&step.distance[step.permanentNode]);check(*step.distance[step.permanentNode]>=last);last=*step.distance[step.permanentNode];for(std::size_t i=0;i<g.nodeCount;++i)if(!permanent[i]&&step.distance[i])check(*step.distance[i]>=last);}check(r.dijkstraTrace.size()<=g.nodeCount);}
void floydCertificate(const Graph& g){auto r=floydWarshall(g);check(r.sources.size()==g.nodeCount&&r.trace.size()==g.nodeCount+1&&!r.traceTruncated);const auto n=g.nodeCount;std::vector<double> matrix(n*n,INFINITY);for(std::size_t i=0;i<n;++i)matrix[i*n+i]=0;for(const auto& e:g.edges){matrix[e.from*n+e.to]=std::min(matrix[e.from*n+e.to],e.value);if(!g.directed)matrix[e.to*n+e.from]=std::min(matrix[e.to*n+e.from],e.value);}for(std::size_t step=0;step<=n;++step){if(step){auto k=step-1;for(std::size_t i=0;i<n;++i)for(std::size_t j=0;j<n;++j)if(std::isfinite(matrix[i*n+k])&&std::isfinite(matrix[k*n+j]))matrix[i*n+j]=std::min(matrix[i*n+j],matrix[i*n+k]+matrix[k*n+j]);}const auto& snapshot=r.trace[step];check(snapshot.initial==(step==0));for(std::size_t i=0;i<n*n;++i){check(snapshot.distance[i].has_value()==std::isfinite(matrix[i]));if(snapshot.distance[i])near(*snapshot.distance[i],matrix[i]);}}for(const auto& source:r.sources)routeCertificate(g,source);}
template<class Exception,class F>void rejects(F f){bool caught=false;try{f();}catch(const Exception&){caught=true;}check(caught);}
}
